CREATE TABLE jfy_gift  (
id INT NOT NULL AUTO_INCREMENT,
gift_name VARCHAR(32) NOT NULL COMMENT '礼品名称',
at_least_recharge_count INT NOT NULL DEFAULT 1 COMMENT '最少兑换数量',
comments CLOB NOT NULL COMMENT '礼品留言',
content TEXT NOT NULL COMMENT '礼品详情',
cost_price DECIMAL(10, 2) NULL DEFAULT NULL COMMENT '成本价',
cover VARCHAR(255) NOT NULL COMMENT '封面',
covers CLOB NOT NULL COMMENT '礼品图片库',
description VARCHAR(62) NOT NULL DEFAULT '' COMMENT '礼品备注',
express_type CLOB NOT NULL COMMENT '配送方式',
gift_type INT NOT NULL COMMENT '礼品类型：1：实物；2：虚拟；3：优惠券；4：积分券',
has_props TINYINT NOT NULL DEFAULT 0 COMMENT '是否有多个属性',
is_limit_sell TINYINT NOT NULL DEFAULT 0 COMMENT '是否限购',
limit_customer_tags CLOB NOT NULL COMMENT '语序购买的会员标签',
limit_sell_custom TINYINT NOT NULL DEFAULT 0 COMMENT '是否开启允许购买的会员标签',
limit_sell_cycle VARCHAR(32) NOT NULL DEFAULT '' COMMENT '限购周期',
limit_sell_cycle_count INT NOT NULL COMMENT '限购期内允许购买的数量',
limit_sell_type TINYINT NOT NULL COMMENT '限购类型',
market_price DECIMAL(10, 2) NOT NULL COMMENT '市场价',
out_sn VARCHAR(255) NOT NULL COMMENT '内部编码',
props CLOB NOT NULL COMMENT '规格',
skus CLOB NOT NULL COMMENT 'SKU',
score_price DECIMAL(10, 2) NOT NULL COMMENT '兑换所需积分',
stock INT NOT NULL COMMENT '库存',
create_at DATETIME(0) NOT NULL COMMENT '创建日期',
store_id INT NOT NULL COMMENT '所属商城',
status INT NULL DEFAULT 1 COMMENT '1：下架；20：审核中；30：复审中；99：上架',
view_count INT NOT NULL DEFAULT 0 COMMENT '访问量',
sell_count INT NULL DEFAULT 0 COMMENT '销量',
PRIMARY KEY (id)
);


